let retireDialog=false;
function askRetire(){if(!S.run)return;if(busy)return toast('行動が終わってからリタイアできます');clearDrag();retireDialog=true;render()}
function cancelRetire(){retireDialog=false;render()}
function confirmRetire(){if(!S.run||!retireDialog||busy)return;clearDrag();healthTimers.forEach(clearTimeout);healthTimers=[];healthVisuals.clear();S.run=null;S.last=null;retireDialog=false;page='home';target=0;msg='';render();toast('ランをリタイアしました。今回の報酬は破棄されました。')}
retreat=function(){askRetire()};
const renderRetirementBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderRetirementBase();if(S.run){$('nav').innerHTML+=`<button class="retire-button" onclick="askRetire()" ${busy?'disabled':''}>リタイア</button>`;if(retireDialog)$('app').innerHTML+=`<div class="retire-overlay" role="dialog" aria-modal="true" aria-labelledby="retire-title"><div class="retire-panel"><h2 id="retire-title">ランをリタイアしますか？</h2><p>今回のランで獲得した金・パック・潜在カード・遺物を破棄し、拠点に戻ります。<br>出発前から所持していたカード・金・パックは保持されます。</p><div class="toolbar"><button onclick="cancelRetire()">探索を続ける</button><button class="primary" onclick="confirmRetire()">報酬を破棄してリタイア</button></div></div></div>`}};
// Apply revised stats to saved encounters once without restoring lost HP.
if(S.run?.enemies&&S.run.mode==='battle'){let r=S.run;for(let e of r.enemies){if(e.behavior==='plated'&&e.configRev!==2&&e.configRev!==3){e.hp=Math.min(20,Math.ceil(e.hp/e.max*20));e.max=20;e.plate=Math.max(0,35-r.turn);let oldGranted=Math.max(0,25-r.turn),newGranted=Math.max(0,36-r.turn);e.block+=Math.max(0,newGranted-oldGranted);e.configRev=2}if(e.behavior==='ravager'){e.ability='激昂：毎ターン攻撃+2。5ターン目から2回攻撃。速攻で倒そう。';prepareEncounterTurn({...r,enemies:[e]})}if(e.boss&&e.max!==200){e.hp=Math.min(200,Math.ceil(e.hp/e.max*200));e.max=200}}if(r.kind==='boss')bossPlan(r)}
